class Solution {
    struct TrieNode {
        int next[2] = {0, 0};
        int count = 0;
    };
    vector<TrieNode> trie;

    void insert(int val) {
        int u = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            if (!trie[u].next[b]) {
                trie[u].next[b] = trie.size();
                trie.emplace_back();
            }
            u = trie[u].next[b];
            trie[u].count++;
        }
    }

    void remove(int val) {
        int u = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            u = trie[u].next[b];
            trie[u].count--;
        }
    }

    int query(int val) {
        int u = 0, ans = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            int want = 1 - b;
            if (trie[u].next[want] && trie[trie[u].next[want]].count > 0) {
                ans |= (1 << i);
                u = trie[u].next[want];
            } else {
                u = trie[u].next[b];
            }
        }
        return ans;
    }

public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        int n = parents.size();
        vector<vector<int>> children(n);
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) root = i;
            else children[parents[i]].push_back(i);
        }

        vector<vector<pair<int, int>>> qByNode(n);
        for (int i = 0; i < queries.size(); i++) {
            qByNode[queries[i][0]].push_back({i, queries[i][1]});
        }

        trie.emplace_back();
        vector<int> ans(queries.size());

        auto dfs = [&](auto& self, int u) -> void {
            insert(u);
            for (auto& [qIdx, val] : qByNode[u]) ans[qIdx] = query(val);
            for (int v : children[u]) self(self, v);
            remove(u);
        };

        dfs(dfs, root);
        return ans;
    }
};

class Solution {
    static class Node {
        int[] next = new int[2];
        int count = 0;
    }
    private java.util.List<Node> trie;

    private void insert(int val) {
        int u = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            if (trie.get(u).next[b] == 0) {
                trie.get(u).next[b] = trie.size();
                trie.add(new Node());
            }
            u = trie.get(u).next[b];
            trie.get(u).count++;
        }
    }

    private void remove(int val) {
        int u = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            u = trie.get(u).next[b];
            trie.get(u).count--;
        }
    }

    private int query(int val) {
        int u = 0, ans = 0;
        for (int i = 17; i >= 0; i--) {
            int b = (val >> i) & 1;
            int want = 1 - b;
            int nextNode = trie.get(u).next[want];
            if (nextNode != 0 && trie.get(nextNode).count > 0) {
                ans |= (1 << i);
                u = nextNode;
            } else {
                u = trie.get(u).next[b];
            }
        }
        return ans;
    }

    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        java.util.List<Integer>[] children = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new java.util.ArrayList<>();
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) root = i;
            else children[parents[i]].add(i);
        }

        java.util.List<int[]>[] qByNode = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) qByNode[i] = new java.util.ArrayList<>();
        for (int i = 0; i < queries.length; i++) {
            qByNode[queries[i][0]].add(new int[]{i, queries[i][1]});
        }

        trie = new java.util.ArrayList<>();
        trie.add(new Node());
        int[] ans = new int[queries.length];
        dfs(root, children, qByNode, ans);
        return ans;
    }

    private void dfs(int u, java.util.List<Integer>[] children, java.util.List<int[]>[] qByNode, int[] ans) {
        insert(u);
        for (int[] q : qByNode[u]) ans[q[0]] = query(q[1]);
        for (int v : children[u]) dfs(v, children, qByNode, ans);
        remove(u);
    }
}

